+
+  const later = element('button', `text-action later-action${bookmark.readLater ? ' active' : ''}`,
+    state.view === 'later' ? 'Mark as read' : bookmark.readLater ? '✓ In read later' : '+ Read later');
+  later.type = 'button';
+  later.dataset.action = 'toggle-later';
+  actions.append(later);
+
+  const edit = element('button', 'text-action', 'Edit');
+  edit.type = 'button';
+  edit.dataset.action = 'edit';
+  actions.append(edit);
+
+  const remove = element('button', 'text-action delete-action', 'Delete');
+  remove.type = 'button';
+  remove.dataset.action = 'ask-delete';
+  actions.append(remove);
+  side.append(actions);
+  card.append(content, side);
+
+  if (state.deleteConfirmId === bookmark.id) {
+    const confirmation = element('div', 'delete-confirm');
+    confirmation.append(element('span', '', 'Delete this bookmark? This cannot be undone.'));
+    const cancel = element('button', 'text-action', 'Cancel');
+    cancel.type = 'button';
+    cancel.dataset.action = 'cancel-delete';
+    const confirm = element('button', 'danger-button', 'Delete bookmark');
+    confirm.type = 'button';
+    confirm.dataset.action = 'confirm-delete';
+    confirmation.append(cancel, confirm);
+    card.append(confirmation);
+  }
+  return card;
+}
+
+function emptyCopy() {
+  if (state.query) return 'No saved pages match that search. Clear the search to see your full collection.';
+  if (state.tag) return `No bookmarks are tagged ${state.tag}.`;
+  if (state.view === 'later') return 'Nothing waiting to be read. Pages you set aside will appear here.';
+  return 'Your collection is empty. Save a web address above whenever you’re ready.';
+}
+
+function render() {
+  const visible = visibleBookmarks();
+  const laterTotal = state.bookmarks.filter((bookmark) => bookmark.readLater).length;
+  laterCount.textContent = laterTotal;
+  document.querySelectorAll('[data-view]').forEach((button) => button.classList.toggle('active', button.dataset.view === state.view));
+
+  sectionKicker.textContent = state.view === 'later' ? 'Reading queue' : 'Collection';
+  collectionTitle.textContent = state.tag ? state.tag : state.view === 'later' ? 'Read later' : 'All bookmarks';
+  clearTag.hidden = !state.tag;
+  if (state.tag) clearTag.textContent = `${state.tag} ×`;
+  resultCount.textContent = state.query || state.tag || state.view === 'later'
+    ? `${visible.length} of ${state.bookmarks.length} bookmarks`
+    : `${state.bookmarks.length} bookmark${state.bookmarks.length === 1 ? '' : 's'}`;
+
+  list.replaceChildren();
+  if (!visible.length) {
+    list.append(element('div', 'empty-state', emptyCopy()));
+  } else {
+    visible.forEach((bookmark) => list.append(makeCard(bookmark)));
+  }
+}
+
+function showToast(message) {
+  toast.textContent = message;
+  toast.hidden = false;
+  clearTimeout(showToast.timeout);
+  showToast.timeout = setTimeout(() => { toast.hidden = true; }, 3600);
+}
+
+function showSaveMessage(message, kind = '') {
+  saveMessage.textContent = message;
+  saveMessage.className = `form-message ${kind}`.trim();
+}
+
+function openEditor(bookmark) {
+  state.editingId = bookmark.id;
+  editUrl.value = bookmark.url;
+  editTitle.value = bookmark.title;
+  editDescription.value = bookmark.description;
+  editTags.value = bookmark.tags.join(', ');
+  editMessage.textContent = '';
+  editMessage.className = 'dialog-message';
+  editDialog.showModal();
+}
+
+saveForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  showSaveMessage('');
+  saveButton.disabled = true;
+  saveButton.querySelector('.button-label').hidden = true;
+  saveButton.querySelector('.button-progress').hidden = false;
+  try {
+    const data = await request('/api/bookmarks', {
+      method: 'POST',
+      body: JSON.stringify({ url: saveUrl.value })
+    });
+    state.bookmarks.unshift(data.bookmark);
+    state.view = 'all';
+    state.tag = '';
+    state.attentionId = data.bookmark.id;
+    saveUrl.value = '';
+    render();
+    showSaveMessage(data.metadataUnavailable
+      ? 'Saved without page details — you can edit them anytime.'
+      : 'Saved — title and description added automatically.', 'success');
+    document.querySelector(`[data-id="${data.bookmark.id}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
+  } catch (error) {
+    if (error.code === 'duplicate' && error.details.bookmark) {
+      const existing = error.details.bookmark;
+      state.view = 'all';
+      state.query = '';
+      state.tag = '';
+      search.value = '';
+      state.attentionId = existing.id;
+      render();
+      showSaveMessage('Already saved — showing your existing bookmark.', 'success');
+      const editExisting = element('button', 'text-action', 'Edit existing');
+      editExisting.type = 'button';
+      editExisting.addEventListener('click', () => openEditor(existing));
+      saveMessage.append(' ', editExisting);
+      document.querySelector(`[data-id="${existing.id}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
+    } else {
+      showSaveMessage(error.message, 'error');
+      saveUrl.focus();
+    }
+  } finally {
+    saveButton.disabled = false;
+    saveButton.querySelector('.button-label').hidden = false;
+    saveButton.querySelector('.button-progress').hidden = true;
+  }
+});
+
+search.addEventListener('input', () => {
+  state.query = search.value;
+  state.deleteConfirmId = null;
+  render();
+});
+
+document.querySelector('.views').addEventListener('click', (event) => {
+  const button = event.target.closest('[data-view]');
+  if (!button) return;
+  state.view = button.dataset.view;
+  state.tag = '';
+  state.deleteConfirmId = null;
+  render();
+});
+
+clearTag.addEventListener('click', () => {
+  state.tag = '';
+  render();
+});
+
+list.addEventListener('click', async (event) => {
+  const action = event.target.closest('[data-action]');
+  if (!action) return;
+  const card = action.closest('[data-id]');
+  const id = Number(card?.dataset.id);
+  const bookmark = state.bookmarks.find((item) => item.id === id);
+  if (!bookmark) return;
+
+  if (action.dataset.action === 'filter-tag') {
+    state.tag = action.dataset.tag;
+    state.deleteConfirmId = null;
+    render();
+    return;
+  }
+  if (action.dataset.action === 'edit') {
+    openEditor(bookmark);
+    return;
+  }
+  if (action.dataset.action === 'ask-delete') {
+    state.deleteConfirmId = id;
+    render();
+    return;
+  }
+  if (action.dataset.action === 'cancel-delete') {
+    state.deleteConfirmId = null;
+    render();
+    return;
+  }
+  if (action.dataset.action === 'confirm-delete') {
+    try {
+      await request(`/api/bookmarks/${id}`, { method: 'DELETE' });
+      state.bookmarks = state.bookmarks.filter((item) => item.id !== id);
+      state.deleteConfirmId = null;
+      render();
+      showToast('Bookmark deleted.');
+      if (!state.bookmarks.length) saveUrl.focus();
+    } catch (error) {
+      showToast(error.message);
+    }
+    return;
+  }
+  if (action.dataset.action === 'toggle-later') {
+    try {
+      const data = await request(`/api/bookmarks/${id}`, {
+        method: 'PATCH',
+        body: JSON.stringify({ readLater: !bookmark.readLater })
+      });
+      state.bookmarks = state.bookmarks.map((item) => item.id === id ? data.bookmark : item);
+      render();
+      showToast(data.bookmark.readLater ? 'Added to read later.' : 'Marked as read.');
+    } catch (error) {
+      showToast(error.message);
+    }
+  }
+});
+
+editForm.addEventListener('submit', async (event) => {
+  event.preventDefault();
+  const saveEdit = document.querySelector('#save-edit');
+  saveEdit.disabled = true;
+  editMessage.textContent = '';
+  try {
+    const data = await request(`/api/bookmarks/${state.editingId}`, {
+      method: 'PATCH',
+      body: JSON.stringify({
+        url: editUrl.value,
+        title: editTitle.value,
+        description: editDescription.value,
+        tags: editTags.value.split(',').map((tag) => tag.trim()).filter(Boolean)
+      })
+    });
+    state.bookmarks = state.bookmarks.map((item) => item.id === data.bookmark.id ? data.bookmark : item);
+    state.attentionId = data.bookmark.id;
+    editDialog.close();
+    render();
+    showToast('Changes saved.');
+  } catch (error) {
+    editMessage.textContent = error.message;
+    editMessage.className = 'dialog-message error';
+    if (error.code === 'duplicate' || error.code === 'invalid_address') editUrl.focus();
+  } finally {
+    saveEdit.disabled = false;
+  }
+});
+
+function closeEditor() {
+  editDialog.close();
+  state.editingId = null;
+}
+document.querySelector('#close-edit').addEventListener('click', closeEditor);
+document.querySelector('#cancel-edit').addEventListener('click', closeEditor);
+
+async function initialize() {
+  try {
+    const data = await request('/api/bookmarks');
+    state.bookmarks = data.bookmarks;
+    loading.hidden = true;
+    render();
+    app.dataset.harnessReady = 'true';
+  } catch {
+    loading.textContent = 'The collection could not be opened. Refresh the page to try again.';
+  }
+}
+
+initialize();
*** End Patch";
text(await tools.apply_patch(patch));

/work/implementation/public/styles.css.content:
:root {
  color-scheme: light;
  --ink: #1b2521;
  --muted: #68726d;
  --paper: #f5f2ea;
  --surface: #fffdf8;
  --surface-strong: #ffffff;
  --line: #dcd6c9;
  --green: #1b6f55;
  --green-dark: #0e4f3a;
  --green-pale: #e8f2ed;
  --gold: #e8ae4d;
  --danger: #9a3e32;
  --danger-pale: #faebe6;
  --shadow: 0 16px 45px rgba(38, 47, 42, .08);
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 90% -5%, rgba(232, 174, 77, .2), transparent 31rem),
    linear-gradient(180deg, #faf8f2 0, var(--paper) 28rem);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button, input, textarea { font: inherit; }
button { cursor: pointer; }

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.topbar {
  width: min(1120px, calc(100% - 40px));
  margin: 0 auto;
  min-height: 82px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  border-bottom: 1px solid rgba(151, 145, 132, .28);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--ink);
  text-decoration: none;
  font: 700 1.35rem Georgia, serif;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border-radius: 9px 9px 9px 2px;
  background: var(--green);
  color: white;
  font: 700 1rem Georgia, serif;
}

.views { display: flex; gap: 7px; }

.view-button {
  min-height: 38px;
  padding: 7px 12px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  font-size: .88rem;
  font-weight: 720;
}

.view-button:hover { color: var(--ink); background: rgba(255,255,255,.55); }
.view-button.active { color: var(--ink); border-color: var(--line); background: var(--surface); }

.count-badge {
  display: inline-grid;
  place-items: center;
  min-width: 20px;
  height: 20px;
  margin-left: 5px;
  padding: 0 5px;
  border-radius: 99px;
  background: var(--gold);
  color: #3f2b08;
  font-size: .71rem;
}

main { width: min(960px, calc(100% - 40px)); margin: 0 auto; padding: 72px 0 100px; }
.intro { max-width: 820px; }
.eyebrow, .section-kicker { margin: 0 0 9px; color: var(--green); font-size: .76rem; font-weight: 820; letter-spacing: .12em; text-transform: uppercase; }
h1 { max-width: 700px; margin: 0; font: 700 clamp(2.35rem, 6vw, 4.35rem)/.98 Georgia, serif; letter-spacing: -.045em; }
.lede { max-width: 670px; margin: 18px 0 30px; color: var(--muted); font-size: 1.07rem; line-height: 1.6; }

.save-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 9px;
  max-width: 820px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface-strong);
  box-shadow: var(--shadow);
}

.save-form input {
  min-width: 0;
  padding: 13px 14px;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
}

.save-form:focus-within { border-color: #8daf9f; box-shadow: 0 0 0 3px rgba(27,111,85,.1), var(--shadow); }

.primary-button, .secondary-button {
  min-height: 46px;
  padding: 10px 17px;
  border: 0;
  border-radius: 10px;
  font-weight: 780;
}
.primary-button { background: var(--green); color: white; }
.primary-button:hover { background: var(--green-dark); }
.primary-button:disabled { cursor: wait; opacity: .72; }
.secondary-button { border: 1px solid var(--line); background: transparent; color: var(--ink); }
.secondary-button:hover { background: #f0ece3; }

.form-message { min-height: 23px; margin: 11px 5px 0; color: var(--muted); font-size: .88rem; }
.form-message.error, .dialog-message.error { color: var(--danger); font-weight: 680; }
.form-message.success { color: var(--green-dark); }

.collection { margin-top: 76px; }
.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding-bottom: 25px; border-bottom: 1px solid var(--line); }
.search-field { position: relative; width: min(510px, 100%); }
.search-field svg { position: absolute; left: 13px; top: 50%; width: 18px; translate: 0 -50%; fill: none; stroke: var(--muted); stroke-width: 1.8; }
.search-field input { width: 100%; min-height: 45px; padding: 10px 13px 10px 42px; border: 1px solid var(--line); border-radius: 11px; outline: 0; background: var(--surface); color: var(--ink); }
.search-field input:focus { border-color: #8daf9f; box-shadow: 0 0 0 3px rgba(27,111,85,.1); }
.result-count { margin: 0; color: var(--muted); font-size: .84rem; white-space: nowrap; }
.collection-heading { display: flex; justify-content: space-between; align-items: end; gap: 20px; margin: 35px 0 16px; }
.collection-heading h2 { margin: 0; font: 700 1.65rem Georgia, serif; }
.filter-chip { min-height: 34px; padding: 6px 11px; border: 1px solid #b9ccc3; border-radius: 999px; background: var(--green-pale); color: var(--green-dark); font-size: .8rem; font-weight: 760; }

.loading-state, .empty-state {
  padding: 50px 24px;
  border: 1px dashed #c9c1b3;
  border-radius: 15px;
  background: rgba(255,253,248,.55);
  color: var(--muted);
  text-align: center;
  line-height: 1.5;
}

.bookmark-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 24px;
  padding: 23px 24px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface);
  box-shadow: 0 7px 24px rgba(38,47,42,.045);
  transition: border-color .18s, box-shadow .18s;
}
.bookmark-card + .bookmark-card { margin-top: 11px; }
.bookmark-card.attention { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(232,174,77,.16), var(--shadow); }
.card-source { margin: 0 0 7px; color: var(--green); font-size: .76rem; font-weight: 830; letter-spacing: .08em; text-transform: uppercase; }
.card-title { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; margin: 0; font: 700 1.18rem/1.28 Georgia, serif; }
.card-title a { color: var(--ink); text-decoration: none; }
.card-title a:hover { color: var(--green-dark); text-decoration: underline; text-underline-offset: 3px; }
.card-description { display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; max-width: 680px; margin: 8px 0 0; color: var(--muted); font-size: .92rem; line-height: 1.5; }
.tag-row { display: flex; flex-wrap: wrap; align-items: center; gap: 7px; margin-top: 14px; }
.tag-button { min-height: 0; padding: 5px 9px; border: 1px solid #c8d8d0; border-radius: 999px; background: var(--green-pale); color: var(--green-dark); font-size: .75rem; font-weight: 760; }
.tag-button:hover { border-color: #92b3a3; }
.more-tags { color: var(--muted); font-size: .75rem; font-weight: 700; }
.card-side { display: flex; flex-direction: column; align-items: flex-end; justify-content: space-between; gap: 20px; }
.saved-time { color: var(--muted); font-size: .77rem; white-space: nowrap; }
.card-actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 7px; }
.text-action { min-height: 33px; padding: 6px 9px; border: 1px solid var(--line); border-radius: 8px; background: transparent; color: var(--ink); font-size: .77rem; font-weight: 710; }
.text-action:hover { background: #f0ece3; }
.later-action { color: var(--green-dark); border-color: #bed1c8; background: #f2f7f4; }
.later-action.active { background: #dcece4; }
.delete-action { color: var(--danger); border-color: #dfc1ba; }
.delete-confirm { grid-column: 1 / -1; display: flex; align-items: center; gap: 9px; margin-top: -4px; padding: 11px 12px; border-radius: 10px; background: var(--danger-pale); color: #6f2c22; font-size: .83rem; }
.delete-confirm span { margin-right: auto; }
.danger-button { min-height: 34px; padding: 6px 10px; border: 0; border-radius: 8px; background: var(--danger); color: white; font-size: .77rem; font-weight: 750; }

.edit-dialog { width: min(650px, calc(100% - 30px)); max-height: calc(100vh - 40px); padding: 0; border: 1px solid var(--line); border-radius: 17px; background: var(--surface); color: var(--ink); box-shadow: 0 28px 90px rgba(21,30,26,.26); }
.edit-dialog::backdrop { background: rgba(22,31,27,.45); backdrop-filter: blur(3px); }
.edit-dialog form { padding: 25px; }
.dialog-heading { display: flex; align-items: start; justify-content: space-between; margin-bottom: 22px; }
.dialog-heading h2 { margin: 0; font: 700 1.65rem Georgia, serif; }
.icon-button { width: 35px; height: 35px; border: 1px solid var(--line); border-radius: 9px; background: transparent; color: var(--muted); font-size: 1.4rem; line-height: 1; }
.edit-dialog label { display: grid; gap: 7px; margin-top: 14px; color: var(--muted); font-size: .81rem; font-weight: 760; }
.edit-dialog input, .edit-dialog textarea { width: 100%; padding: 11px 12px; border: 1px solid var(--line); border-radius: 9px; outline: 0; background: white; color: var(--ink); resize: vertical; }
.edit-dialog input:focus, .edit-dialog textarea:focus { border-color: #8daf9f; box-shadow: 0 0 0 3px rgba(27,111,85,.1); }
.field-help { font-size: .73rem; font-weight: 500; }
.dialog-message { min-height: 21px; margin: 12px 0 0; font-size: .83rem; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 9px; margin-top: 20px; }

.toast { position: fixed; z-index: 20; left: 50%; bottom: 28px; translate: -50% 0; max-width: calc(100% - 30px); padding: 12px 17px; border-radius: 10px; background: var(--ink); color: white; box-shadow: 0 16px 45px rgba(0,0,0,.24); font-size: .86rem; }

@media (max-width: 720px) {
  .topbar { width: min(100% - 28px, 1120px); min-height: 72px; align-items: flex-start; padding: 18px 0; }
  .views { flex-direction: column; align-items: stretch; }
  .view-button { min-height: 32px; padding-block: 4px; text-align: right; }
  main { width: min(100% - 28px, 960px); padding-top: 48px; }
  .save-form { grid-template-columns: 1fr; }
  .toolbar { align-items: flex-start; flex-direction: column; gap: 10px; }
  .search-field { width: 100%; }
  .bookmark-card { grid-template-columns: 1fr; gap: 16px; padding: 19px; }
  .card-side { align-items: flex-start; gap: 13px; }
  .card-actions { justify-content: flex-start; }
  .delete-confirm { flex-wrap: wrap; }
  .delete-confirm span { flex-basis: 100%; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

/work/implementation/public/app.js.content:
const state = {
  bookmarks: [],
  view: 'all',
  query: '',
  tag: '',
  deleteConfirmId: null,
  attentionId: null,
  editingId: null
};

const app = document.querySelector('#app');
const list = document.querySelector('#bookmark-list');
const loading = document.querySelector('#loading-state');
const saveForm = document.querySelector('#save-form');
const saveUrl = document.querySelector('#save-url');
const saveButton = document.querySelector('#save-button');
const saveMessage = document.querySelector('#save-message');
const search = document.querySelector('#search');
const resultCount = document.querySelector('#result-count');
const collectionTitle = document.querySelector('#collection-title');
const sectionKicker = document.querySelector('#section-kicker');
const clearTag = document.querySelector('#clear-tag');
const laterCount = document.querySelector('#later-count');
const editDialog = document.querySelector('#edit-dialog');
const editForm = document.querySelector('#edit-form');
const editUrl = document.querySelector('#edit-url');
const editTitle = document.querySelector('#edit-title');
const editDescription = document.querySelector('#edit-description');
const editTags = document.querySelector('#edit-tags');
const editMessage = document.querySelector('#edit-message');
const toast = document.querySelector('#toast');

function element(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

async function request(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    headers: { 'content-type': 'application/json', ...(options.headers || {}) }
  });
  const data = response.status === 204 ? null : await response.json();
  if (!response.ok) {
    const error = new Error(data?.error?.message || 'Something went wrong.');
    error.status = response.status;
    error.code = data?.error?.code;
    error.details = data?.error;
    throw error;
  }
  return data;
}

function relativeTime(iso) {
  const seconds = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (seconds < 60) return 'Saved just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `Saved ${minutes}m ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `Saved ${hours}h ago`;
  const days = Math.floor(hours / 24);
  if (days === 1) return 'Saved yesterday';
  if (days < 7) return `Saved ${days} days ago`;
  return `Saved ${new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric' }).format(new Date(iso))}`;
}

function visibleBookmarks() {
  const normalizedQuery = state.query.trim().toLocaleLowerCase();
  const normalizedTag = state.tag.toLocaleLowerCase();
  return state.bookmarks.filter((bookmark) => {
    if (state.view === 'later' && !bookmark.readLater) return false;
    if (normalizedTag && !bookmark.tags.some((tag) => tag.toLocaleLowerCase() === normalizedTag)) return false;
    if (normalizedQuery && ![bookmark.title, bookmark.description, bookmark.source]
      .some((value) => value.toLocaleLowerCase().includes(normalizedQuery))) return false;
    return true;
  });
}

function makeTagRow(bookmark) {
  if (!bookmark.tags.length) return null;
  const row = element('div', 'tag-row');
  bookmark.tags.slice(0, 4).forEach((tag) => {
    const button = element('button', 'tag-button', tag);
    button.type = 'button';
    button.dataset.action = 'filter-tag';
    button.dataset.tag = tag;
    row.append(button);
  });
  if (bookmark.tags.length > 4) row.append(element('span', 'more-tags', `+${bookmark.tags.length - 4} more tags`));
  return row;
}

function makeCard(bookmark) {
  const card = element('article', 'bookmark-card');
  card.dataset.id = bookmark.id;
  if (state.attentionId === bookmark.id) card.classList.add('attention');

  const content = element('div', 'card-content');
  content.append(element('p', 'card-source', bookmark.source));
  const heading = element('h3', 'card-title');
  const link = element('a', '', bookmark.title);
  link.href = bookmark.url;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  heading.append(link);
  content.append(heading);
  if (bookmark.description) content.append(element('p', 'card-description', bookmark.description));
  const tagRow = makeTagRow(bookmark);
  if (tagRow) content.append(tagRow);

  const side = element('div', 'card-side');
  side.append(element('span', 'saved-time', relativeTime(bookmark.createdAt)));
  const actions = element('div', 'card-actions');

  const later = element('button', `text-action later-action${bookmark.readLater ? ' active' : ''}`,
    state.view === 'later' ? 'Mark as read' : bookmark.readLater ? '✓ In read later' : '+ Read later');
  later.type = 'button';
  later.dataset.action = 'toggle-later';
  actions.append(later);

  const edit = element('button', 'text-action', 'Edit');
  edit.type = 'button';
  edit.dataset.action = 'edit';
  actions.append(edit);

  const remove = element('button', 'text-action delete-action', 'Delete');
  remove.type = 'button';
  remove.dataset.action = 'ask-delete';
  actions.append(remove);
  side.append(actions);
  card.append(content, side);

  if (state.deleteConfirmId === bookmark.id) {
    const confirmation = element('div', 'delete-confirm');
    confirmation.append(element('span', '', 'Delete this bookmark? This cannot be undone.'));
    const cancel = element('button', 'text-action', 'Cancel');
    cancel.type = 'button';
    cancel.dataset.action = 'cancel-delete';
    const confirm = element('button', 'danger-button', 'Delete bookmark');
    confirm.type = 'button';
    confirm.dataset.action = 'confirm-delete';
    confirmation.append(cancel, confirm);
    card.append(confirmation);
  }
  return card;
}

function emptyCopy() {
  if (state.query) return 'No saved pages match that search. Clear the search to see your full collection.';
  if (state.tag) return `No bookmarks are tagged ${state.tag}.`;
  if (state.view === 'later') return 'Nothing waiting to be read. Pages you set aside will appear here.';
  return 'Your collection is empty. Save a web address above whenever you’re ready.';
}

function render() {
  const visible = visibleBookmarks();
  const laterTotal = state.bookmarks.filter((bookmark) => bookmark.readLater).length;
  laterCount.textContent = laterTotal;
  document.querySelectorAll('[data-view]').forEach((button) => button.classList.toggle('active', button.dataset.view === state.view));

  sectionKicker.textContent = state.view === 'later' ? 'Reading queue' : 'Collection';
  collectionTitle.textContent = state.tag ? state.tag : state.view === 'later' ? 'Read later' : 'All bookmarks';
  clearTag.hidden = !state.tag;
  if (state.tag) clearTag.textContent = `${state.tag} ×`;
  resultCount.textContent = state.query || state.tag || state.view === 'later'
    ? `${visible.length} of ${state.bookmarks.length} bookmarks`
    : `${state.bookmarks.length} bookmark${state.bookmarks.length === 1 ? '' : 's'}`;

  list.replaceChildren();
  if (!visible.length) {
    list.append(element('div', 'empty-state', emptyCopy()));
  } else {
    visible.forEach((bookmark) => list.append(makeCard(bookmark)));
  }
}

function showToast(message) {
  toast.textContent = message;
  toast.hidden = false;
  clearTimeout(showToast.timeout);
  showToast.timeout = setTimeout(() => { toast.hidden = true; }, 3600);
}

function showSaveMessage(message, kind = '') {
  saveMessage.textContent = message;
  saveMessage.className = `form-message ${kind}`.trim();
}

function openEditor(bookmark) {
  state.editingId = bookmark.id;
  editUrl.value = bookmark.url;
  editTitle.value = bookmark.title;
  editDescription.value = bookmark.description;
  editTags.value = bookmark.tags.join(', ');
  editMessage.textContent = '';
  editMessage.className = 'dialog-message';
  editDialog.showModal();
}

saveForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  showSaveMessage('');
  saveButton.disabled = true;
  saveButton.querySelector('.button-label').hidden = true;
  saveButton.querySelector('.button-progress').hidden = false;
  try {
    const data = await request('/api/bookmarks', {
      method: 'POST',
      body: JSON.stringify({ url: saveUrl.value })
    });
    state.bookmarks.unshift(data.bookmark);
    state.view = 'all';
    state.tag = '';
    state.attentionId = data.bookmark.id;
    saveUrl.value = '';
    render();
    showSaveMessage(data.metadataUnavailable
      ? 'Saved without page details — you can edit them anytime.'
      : 'Saved — title and description added automatically.', 'success');
    document.querySelector(`[data-id="${data.bookmark.id}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  } catch (error) {
    if (error.code === 'duplicate' && error.details.bookmark) {
      const existing = error.details.bookmark;
      state.view = 'all';
      state.query = '';
      state.tag = '';
      search.value = '';
      state.attentionId = existing.id;
      render();
      showSaveMessage('Already saved — showing your existing bookmark.', 'success');
      const editExisting = element('button', 'text-action', 'Edit existing');
      editExisting.type = 'button';
      editExisting.addEventListener('click', () => openEditor(existing));
      saveMessage.append(' ', editExisting);
      document.querySelector(`[data-id="${existing.id}"]`)?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    } else {
      showSaveMessage(error.message, 'error');
      saveUrl.focus();
    }
  } finally {
    saveButton.disabled = false;
    saveButton.querySelector('.button-label').hidden = false;
    saveButton.querySelector('.button-progress').hidden = true;
  }
});

search.addEventListener('input', () => {
  state.query = search.value;
  state.deleteConfirmId = null;
  render();
});

document.querySelector('.views').addEventListener('click', (event) => {
  const button = event.target.closest('[data-view]');
  if (!button) return;
  state.view = button.dataset.view;
  state.tag = '';
  state.deleteConfirmId = null;
  render();
});

clearTag.addEventListener('click', () => {
  state.tag = '';
  render();
});

list.addEventListener('click', async (event) => {
  const action = event.target.closest('[data-action]');
  if (!action) return;
  const card = action.closest('[data-id]');
  const id = Number(card?.dataset.id);
  const bookmark = state.bookmarks.find((item) => item.id === id);
  if (!bookmark) return;

  if (action.dataset.action === 'filter-tag') {
    state.tag = action.dataset.tag;
    state.deleteConfirmId = null;
    render();
    return;
  }
  if (action.dataset.action === 'edit') {
    openEditor(bookmark);
    return;
  }
  if (action.dataset.action === 'ask-delete') {
    state.deleteConfirmId = id;
    render();
    return;
  }
  if (action.dataset.action === 'cancel-delete') {
    state.deleteConfirmId = null;
    render();
    return;
  }
  if (action.dataset.action === 'confirm-delete') {
    try {
      await request(`/api/bookmarks/${id}`, { method: 'DELETE' });
      state.bookmarks = state.bookmarks.filter((item) => item.id !== id);
      state.deleteConfirmId = null;
      render();
      showToast('Bookmark deleted.');
      if (!state.bookmarks.length) saveUrl.focus();
    } catch (error) {
      showToast(error.message);
    }
    return;
  }
  if (action.dataset.action === 'toggle-later') {
    try {
      const data = await request(`/api/bookmarks/${id}`, {
        method: 'PATCH',
        body: JSON.stringify({ readLater: !bookmark.readLater })
      });
      state.bookmarks = state.bookmarks.map((item) => item.id === id ? data.bookmark : item);
      render();
      showToast(data.bookmark.readLater ? 'Added to read later.' : 'Marked as read.');
    } catch (error) {
      showToast(error.message);
    }
  }
});

editForm.addEventListener('submit', async (event) => {
  event.preventDefault();
  const saveEdit = document.querySelector('#save-edit');
  saveEdit.disabled = true;
  editMessage.textContent = '';
  try {
    const data = await request(`/api/bookmarks/${state.editingId}`, {
      method: 'PATCH',
      body: JSON.stringify({
        url: editUrl.value,
        title: editTitle.value,
        description: editDescription.value,
        tags: editTags.value.split(',').map((tag) => tag.trim()).filter(Boolean)
      })
    });
    state.bookmarks = state.bookmarks.map((item) => item.id === data.bookmark.id ? data.bookmark : item);
    state.attentionId = data.bookmark.id;
    editDialog.close();
    render();
    showToast('Changes saved.');
  } catch (error) {
    editMessage.textContent = error.message;
    editMessage.className = 'dialog-message error';
    if (error.code === 'duplicate' || error.code === 'invalid_address') editUrl.focus();
  } finally {
    saveEdit.disabled = false;
  }
});

function closeEditor() {
  editDialog.close();
  state.editingId = null;
}
document.querySelector('#close-edit').addEventListener('click', closeEditor);
document.querySelector('#cancel-edit').addEventListener('click', closeEditor);

async function initialize() {
  try {
    const data = await request('/api/bookmarks');
    state.bookmarks = data.bookmarks;
    loading.hidden = true;
    render();
    app.dataset.harnessReady = 'true';
  } catch {
    loading.textContent = 'The collection could not be opened. Refresh the page to try again.';
  }
}

initialize();

